        "nh_mark_condition": {"value": "load cell marked NH allowed only if humidity testing to R76 has been conducted on this load cell"}
      }
    },
    {
      "role": "control_and_display_unit",
      "type_designations": ["PM860", "M6215"],
      "alternatives": "OR",
      "characteristics": {
        "display": {"value": "15-inch TFT LCD touch-screen"},
